/* Temporary fictional judging workspace. No network requests or database writes. */
const SEEMA_JUDGE = (()=>{
 const demoOfficer={id:'judge-demo',name:'Judge Preview',officerCode:'DEMO',checkpoint:'Fictional demonstration checkpoint',role:'demo officer'};
 const records=new Map();let serial=1045;const stamp=()=>new Date().toISOString();
 const makeEvent=(action,detail='')=>({id:crypto.randomUUID(),action,detail,created_at:stamp(),officer_name:'Demo Officer'});
 function makeCase(id,name,status,stage,fields,captureTypes){const created=stamp();return {case:{id,traveller_name:name,reference:'FICTIONAL SAMPLE',owner_id:'judge-demo',status,stage,created_at:created,updated_at:created},civilian:null,fields,captures:captureTypes.map(type=>({id:id+'-'+type,kind:type==='face'?'face':'document',document_type:type,source:'sample',filename:'fictional-'+type+'.jpg',mime:'image/jpeg',size:0,superseded:0,created_at:created,fixture:type,url:'/demo/document.jpg'})),checks:[],checksStale:false,run:null,events:[makeEvent('Fictional case prepared','Illustrative evidence for judging; not a real traveller.')],decisions:[]};}
 const a=makeCase('DEMO-1042','Demo Person','flagged','review',{passportName:'DEMO PERSON',visaName:'DEMO PERSON',passportNumber:'EX1234567',nationality:'EXAMPLE REPUBLIC',passportDob:'1994-04-12',visaDob:'1995-04-12',passportExpiry:'2034-04-12'},['passport','visa','face']);
 records.set(a.case.id,a);
 const b=makeCase('DEMO-1043','Sample Traveller B','recapture_needed','documents',{},[]);b.events.unshift(makeEvent('Recapture requested','Sample scenario: a clearer document image is needed.'));records.set(b.case.id,b);
 const c=makeCase('DEMO-1044','Sample Traveller C','supervisor_review','review',{passportDob:'1988-07-08',passportExpiry:'2020-01-01'},[]);c.events.unshift(makeEvent('Referred for supervisor review','Sample scenario: the entered expiry date has passed.'));records.set(c.case.id,c);
 async function checks(r){const {buildChecks}=await import('/check-rules.js');r.checks=buildChecks(r.captures,r.fields);r.checksStale=false;r.run={id:'demo-run',status:r.checks.some(c=>c.state==='flagged')?'flagged':'awaiting_review',created_at:stamp()};}
 const ready=Promise.all([checks(a),checks(c)]);
 const clone=x=>structuredClone(x);
 async function api(path,options={}){await ready;const method=options.method||'GET';const data=typeof options.body==='string'?JSON.parse(options.body):options.body;
  if(path==='/me')return {officer:clone(demoOfficer)};
  if(path==='/cases'&&method==='GET')return {cases:Array.from(records.values()).map(r=>clone(r.case)).sort((a,b)=>b.updated_at.localeCompare(a.updated_at))};
  if(path==='/cases'&&method==='POST'){const id='DEMO-'+serial++;records.set(id,makeCase(id,String(data.travellerName||''),'draft',data.entryMode==='manual'?'details':'documents',{},[]));return {id};}
  const match=path.match(/^\/cases\/([^/]+)(?:\/(fields|stage|captures|checks|decision|civilian))?$/);if(!match)throw new Error('This action is unavailable in the judging demo.');const r=records.get(match[1]);if(!r)throw new Error('Demo case not found.');const action=match[2];
  if(!action&&method==='GET')return clone(r);
  if(action==='stage'){r.case.stage=data.stage;return {ok:true};}
  if(action==='civilian'){const {normalizeCivilian}=await import('/civilian-rules.js');r.civilian={...normalizeCivilian(data),updatedAt:stamp()};r.case.traveller_name=r.civilian.fullName;r.case.updated_at=stamp();r.events.unshift(makeEvent('Civilian details saved',r.civilian.source==='civilian_statement'?'Civilian statement; unverified':'Document transcription; unverified'));return {ok:true};}
  if(action==='fields'){r.fields=clone(data);r.case.traveller_name=data.passportName||data.visaName||r.case.traveller_name;r.case.status='draft';r.checksStale=!!r.run;r.case.updated_at=stamp();r.events.unshift(makeEvent('Demo fields updated','Changes are temporary and reset when this page reloads.'));return {ok:true};}
  if(action==='captures'){const file=data.get('file'),kind=data.get('kind'),type=kind==='face'?'face':data.get('documentType');if(!file?.size||file.size>12*1024*1024)throw new Error('Choose a file smaller than 12 MB.');const {fileType}=await import('/check-rules.js');const mime=fileType(new Uint8Array(await file.arrayBuffer()));if(!mime||(kind==='face'&&mime==='application/pdf'))throw new Error('Use a JPEG, PNG, WebP or PDF document.');for(const capture of r.captures)if(capture.document_type===type)capture.superseded=1;const id=crypto.randomUUID();r.captures.unshift({id,case_id:r.case.id,kind,document_type:type,source:data.get('source'),filename:file.name,mime,size:file.size,superseded:0,created_at:stamp(),url:URL.createObjectURL(file)});r.case.status='draft';r.case.updated_at=stamp();r.checksStale=!!r.run;r.events.unshift(makeEvent('Demo capture added','This image stays in this browser tab. It is not uploaded to officer storage.'));return {id};}
  if(action==='checks'){await checks(r);r.case.status=r.run.status;r.case.stage='review';r.case.updated_at=stamp();r.events.unshift(makeEvent('Available demo checks evaluated','AI checks remain not performed.'));return clone(r);}
  if(action==='decision'){if(data.action==='pass')throw new Error('Required checks are incomplete. This demo case cannot be marked passed.');if(!String(data.reason||'').trim())throw new Error('Enter a reason for the action.');const statuses={recapture:'recapture_needed',supervisor:'supervisor_review',note:'awaiting_review'};if(!statuses[data.action])throw new Error('Choose a review action.');r.case.status=statuses[data.action];r.case.updated_at=stamp();r.decisions.unshift({...data,created_at:stamp(),officer_name:'Judge Preview'});r.events.unshift(makeEvent('Demo action recorded',data.reason));return {ok:true};}
  throw new Error('Unsupported demo action.');
 }
 return {api,officer:demoOfficer};
})();
